def _from_file_uri(path_or_uri):
    if is_uri(path_or_uri):
        if path_or_uri.startswith('file:///'):
            return path_or_uri[7:]  # keep last /
        else:
            raise ValueError('Not a file:/// URI')
    else:
        return path_or_uri

def exists(self, path_glob):
    path_glob = _from_file_uri(path_glob)
    return bool(glob.glob(path_glob))

def rm(self, path_glob):
    path_glob = _from_file_uri(path_glob)
    for path in glob.glob(path_glob):
        if os.path.isdir(path):
            log.debug('Recursively deleting %s' % path)
            shutil.rmtree(path)
        else:
            log.debug('Deleting %s' % path)
            os.remove(path)

def is_uri(uri):
    r"""Return True if *uri* is a URI and contains ``://``
    (we only care about URIs that can describe files)
    """
    return '://' in uri and bool(urlparse(uri).scheme)
